#include <stdio.h>

int bsearch_int(const int arr[], int n, int target) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

int main(void) {
    int nums[] = {2, 4, 6, 8, 10, 12};
    printf("%d\n", bsearch_int(nums, 6, 10));
    printf("%d\n", bsearch_int(nums, 6, 5));
    return 0;
}

