typedef struct {
    const char *name;
    double price;
} Product;

int by_price(const void *a, const void *b) {
    const Product *x = a, *y = b;
    return (x->price > y->price) - (x->price < y->price);
}

int main(void) {
    Product items[] = {
        {"bread", 2.50},
        {"milk", 1.20},
        {"cheese", 7.40},
        {"eggs", 3.00},
        {"honey", 5.90}
    };
    int n = sizeof(items) / sizeof(items[0]);

    qsort(items, n, sizeof(Product), by_price);

    double total = 0;
    for (int i = 0; i < n; i++) {
        printf("%s %.2f\n", items[i].name, items[i].price);
        total += items[i].price;
    }

    double avg = total / n;
    int above = 0;
    for (int i = 0; i < n; i++) {
        if (items[i].price > avg) above++;
    }

    printf("total: %.2f\n", total);
    printf("average: %.2f\n", avg);
    printf("above average: %d\n", above);
    return 0;
}

