#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <algorithm>
#include <cctype>

int main() {
    std::string raw{"  Data Science Rocks  "};

    int vowels = 0;
    for (char c : raw) {
        char l = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        if (l == 'a' || l == 'e' || l == 'i' || l == 'o' || l == 'u') ++vowels;
    }

    std::istringstream in{raw};
    std::vector<std::string> words;
    std::string w;
    while (in >> w) words.push_back(w);

    std::string reversed = raw;
    std::reverse(reversed.begin(), reversed.end());

    std::string joined;
    for (std::size_t i = 0; i < words.size(); ++i) {
        if (i > 0) joined += "_";
        joined += words[i];
    }

    std::cout << raw.size() << '\n';
    std::cout << vowels << '\n';
    std::cout << words.size() << '\n';
    std::cout << reversed << '\n';
    std::cout << joined << '\n';
}

