    std::cout << "size: " << v.size() << '\n';
    std::cout << "sum: " << sum << '\n';
    std::cout << std::fixed << std::setprecision(2) << "average: " << avg << '\n';
    std::cout << "max: " << *std::max_element(v.begin(), v.end()) << '\n';
    std::cout << "min: " << *std::min_element(v.begin(), v.end()) << '\n';

    for (int n : v) {
