#include <iostream>
#include <map>
#include <string>
#include <sstream>
#include <vector>

int main() {
    std::istringstream in{"the fox the dog the cat"};
    std::map<std::string, int> counts;
    std::string word;

    while (in >> word) counts[word]++;

    for (const auto& [w, n] : counts) {
        std::cout << w << ": " << n << '\n';
    }

    std::map<std::size_t, std::vector<std::string>> by_length;
    for (const auto& [w, n] : counts) by_length[w.size()].push_back(w);

    for (const auto& [len, words] : by_length) {
        std::cout << len << ": " << words.size() << '\n';
    }
}

