#include <vector>

int main() {
    std::vector<int> raw{3, 1, 4, 1, 5, 9, 2, 6, 5, 3};
    std::set<int> unique(raw.begin(), raw.end());

    std::cout << raw.size() << " -> " << unique.size() << '\n';
    for (int n : unique) std::cout << n << ' ';
    std::cout << '\n';

    auto result = unique.insert(100);
    std::cout << std::boolalpha << result.second << '\n';
    result = unique.insert(100);
    std::cout << result.second << '\n';

    std::cout << unique.count(4) << ' ' << unique.count(42) << '\n';
}

