#include <iostream>
#include <utility>
#include <tuple>
#include <string>
#include <vector>

std::pair<int, int> min_max(const std::vector<int>& v) {
    int lo = v[0], hi = v[0];
    for (int n : v) {
        if (n < lo) lo = n;
        if (n > hi) hi = n;
    }
    return {lo, hi};
}

int main() {
    auto p = std::make_pair(std::string{"ada"}, 91);
    std::cout << p.first << ' ' << p.second << '\n';

    auto [lo, hi] = min_max({4, 9, 1, 7});
    std::cout << lo << ' ' << hi << '\n';

    std::tuple<std::string, int, double> row{"widget", 7, 12.5};
    std::cout << std::get<0>(row) << ' ' << std::get<1>(row) << '\n';

    auto [name, qty, price] = row;
    std::cout << name << ' ' << qty << ' ' << price << '\n';
}

