#include <iostream>
#include <iomanip>
#include <utility>
#include <vector>

std::pair<int, int> sum_and_count(const std::vector<int>& v) {
    int sum = 0;
    for (int n : v) sum += n;
    return {sum, static_cast<int>(v.size())};
}

int main() {
    auto [sum, count] = sum_and_count({4, 8, 15, 16});

    std::cout << sum << '\n';
    std::cout << count << '\n';
    std::cout << std::fixed << std::setprecision(2)
              << static_cast<double>(sum) / count << '\n';
}

