template <typename T, typename Predicate>
int count_matching(const std::vector<T>& items, Predicate pred) {
    int count = 0;
    for (const auto& item : items) {
        if (pred(item)) ++count;
    }
    return count;
}

template <typename T, typename Operation>
void apply_each(const std::vector<T>& items, Operation op) {
    for (const auto& item : items) std::cout << op(item) << ' ';
    std::cout << '\n';
}

int main() {
    std::vector<int> nums{1, 2, 3, 4, 5, 6};
    std::cout << count_matching(nums, [](int n) { return n % 2 == 0; }) << '\n';
    std::cout << count_matching(nums, [](int n) { return n > 3; }) << '\n';

    apply_each(nums, [](int n) { return n * n; });

    std::vector<std::string> words{"a", "bb", "ccc"};
    std::cout << count_matching(words, [](const std::string& s) { return s.size() > 1; }) << '\n';
}

