    double total = std::accumulate(sales.begin(), sales.end(), 0.0,
        [](double sum, const Sale& s) { return sum + s.amount; });

    auto best = std::max_element(sales.begin(), sales.end(),
        [](const Sale& a, const Sale& b) { return a.amount < b.amount; });

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "total " << total << '\n';
    std::cout << "best " << best->region << ' ' << best->amount << '\n';
    std::cout << "count " << std::count_if(sales.begin(), sales.end(),
        [](const Sale& s) { return s.amount > 1000; }) << '\n';
}

