#include <iostream>
#include <iomanip>
#include <string>
#include <vector>
#include <algorithm>
#include <numeric>

class Product {
    std::string name;
    double price;
    int quantity;
public:
    Product(std::string n, double p, int q)
        : name{std::move(n)}, price{p}, quantity{q} {}

    const std::string& get_name() const { return name; }
    double get_price() const { return price; }
    int get_quantity() const { return quantity; }
    double value() const { return price * quantity; }
};

int main() {
    std::vector<Product> items{
        {"bread", 2.50, 3},
        {"cheese", 7.40, 1},
        {"milk", 1.20, 6},
        {"honey", 5.90, 2}
    };

    std::sort(items.begin(), items.end(),
              [](const Product& a, const Product& b) { return a.value() > b.value(); });

    std::cout << std::fixed << std::setprecision(2);
    for (const auto& p : items) {
        std::cout << p.get_name() << ' ' << p.get_price() << " x "
                  << p.get_quantity() << " = " << p.value() << '\n';
    }

    double total = std::accumulate(items.begin(), items.end(), 0.0,
        [](double sum, const Product& p) { return sum + p.value(); });

    std::cout << "total " << total << '\n';
    std::cout << "over 20: " << std::count_if(items.begin(), items.end(),
        [](const Product& p) { return p.value() > 20.0; }) << '\n';
}

