#include <iostream>
#include <iomanip>
#include <sstream>
#include <string>

int main() {
    std::istringstream data{"ada,91\nbob,78\ncy,95"};
    std::string line;
    int total = 0, count = 0;

    while (std::getline(data, line)) {
        std::istringstream parts{line};
        std::string name, score;
        std::getline(parts, name, ',');
        std::getline(parts, score, ',');
        std::cout << name << ' ' << score << '\n';
        total += std::stoi(score);
        ++count;
    }

    std::cout << std::fixed << std::setprecision(1)
              << static_cast<double>(total) / count << '\n';
}

