class Account {
    private int balance;

    Account(int balance) {
        this.balance = Math.max(0, balance);
    }

    int getBalance() {
        return balance;
    }

    boolean deposit(int amount) {
        if (amount <= 0) return false;
        balance += amount;
        return true;
    }

    boolean withdraw(int amount) {
        if (amount <= 0 || amount > balance) return false;
        balance -= amount;
        return true;
    }
}

