import java.util.List;

class Shape {
    double area() { return 0; }
}

class Sq extends Shape {
    double s;
    Sq(double s) { this.s = s; }
    @Override double area() { return s * s; }
}

class Rect extends Shape {
    double w, h;
    Rect(double w, double h) { this.w = w; this.h = h; }
    @Override double area() { return w * h; }
}

class Tri extends Shape {
    double b, h;
    Tri(double b, double h) { this.b = b; this.h = h; }
    @Override double area() { return b * h / 2; }
}

public class Main {
    public static void main(String[] args) {
        List<Shape> shapes = List.of(new Sq(2), new Rect(3, 5), new Tri(6, 4));
        for (Shape s : shapes) System.out.println(s.area());
    }
}

