import java.util.List;

abstract class Employee {
    protected String name;
    Employee(String name) { this.name = name; }

    abstract double pay();

    void payslip() {
        System.out.printf("%s %.2f%n", name, pay());
    }
}

class Salaried extends Employee {
    private double annual;
    Salaried(String name, double annual) {
        super(name);
        this.annual = annual;
    }
    @Override double pay() { return annual / 12; }
}

class Hourly extends Employee {
    private double rate;
    private int hours;
    Hourly(String name, double rate, int hours) {
        super(name);
        this.rate = rate;
        this.hours = hours;
    }
    @Override double pay() { return rate * hours; }
}

public class Main {
    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Salaried("Ada", 60000),
            new Hourly("Bob", 25, 160),
            new Hourly("Cy", 30, 120)
        );

        double total = 0;
        for (Employee e : staff) {
            e.payslip();
            total += e.pay();
        }
        System.out.printf("total %.2f%n", total);
    }
}

