class InsufficientFundsException extends RuntimeException {
    private final int shortfall;

    InsufficientFundsException(String message, int shortfall) {
        super(message);
        this.shortfall = shortfall;
    }

    int getShortfall() {
        return shortfall;
    }
}

public class Main {
    static int withdraw(int balance, int amount) {
        if (amount > balance) {
            throw new InsufficientFundsException("cannot withdraw " + amount, amount - balance);
        }
        return balance - amount;
    }

    public static void main(String[] args) {
        System.out.println(withdraw(100, 40));

        try {
            withdraw(100, 250);
        } catch (InsufficientFundsException e) {
            System.out.println(e.getMessage());
            System.out.println("short by " + e.getShortfall());
        }
    }
}

