import java.util.List;

public class Main {
    static <T> void printAll(List<T> items) {
        for (T item : items) System.out.println(item);
    }

    static <T> T firstOf(List<T> items) {
        return items.get(0);
    }

    static <T extends Comparable<T>> T largest(List<T> items) {
        T best = items.get(0);
        for (T item : items) {
            if (item.compareTo(best) > 0) best = item;
        }
        return best;
    }

    public static void main(String[] args) {
        printAll(List.of(1, 2, 3));
        printAll(List.of("a", "b"));

        String s = firstOf(List.of("first", "second"));
        System.out.println(s);

        System.out.println(largest(List.of(3, 9, 2)));
        System.out.println(largest(List.of("apple", "cherry", "banana")));
    }
}

