import java.util.List;

public class Main {
    static <T> int count(List<T> items) {
        return items.size();
    }

    static <T> T lastOf(List<T> items) {
        return items.get(items.size() - 1);
    }

    static <T extends Comparable<T>> T smallest(List<T> items) {
        T best = items.get(0);
        for (T item : items) {
            if (item.compareTo(best) < 0) best = item;
        }
        return best;
    }

    public static void main(String[] args) {
        List<Integer> nums = List.of(5, 2, 9);
        List<String> words = List.of("pear", "apple", "fig");

        System.out.println(count(nums));
        System.out.println(lastOf(nums));
        System.out.println(smallest(nums));

        System.out.println(count(words));
        System.out.println(lastOf(words));
        System.out.println(smallest(words));
    }
}

