import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

record Product(String name, double price, int quantity) {
    double value() { return price * quantity; }
}

public class Main {
    public static void main(String[] args) {
        List<Product> items = List.of(
            new Product("bread", 2.50, 3),
            new Product("cheese", 7.40, 1),
            new Product("milk", 1.20, 6),
            new Product("honey", 5.90, 2),
            new Product("eggs", 3.00, 4)
        );

        System.out.printf("%.2f%n", items.stream().mapToDouble(Product::value).sum());

        System.out.println(items.stream()
            .sorted(Comparator.comparingDouble(Product::value).reversed())
            .limit(3)
            .map(Product::name)
            .collect(Collectors.joining(", ")));

        System.out.println(items.stream().filter(p -> p.value() > 15).count());
        System.out.printf("%.2f%n", items.stream().mapToDouble(Product::value).average().getAsDouble());
    }
}

