struct Rect {
    width: f64,
    height: f64,
}

impl Rect {
    fn new(width: f64, height: f64) -> Rect {
        Rect { width, height }
    }

    fn square(side: f64) -> Rect {
        Rect::new(side, side)
    }

    fn area(&self) -> f64 {
        self.width * self.height
    }

    fn is_square(&self) -> bool {
        self.width == self.height
    }

    fn scale(&mut self, factor: f64) {
        self.width *= factor;
        self.height *= factor;
    }
}

fn main() {
    let mut r = Rect::new(3.0, 4.0);
    println!("{:?}", r);
    println!("{:.2} {}", r.area(), r.is_square());

    r.scale(2.0);
    println!("{:.2}", r.area());

    let s = Rect::square(5.0);
    println!("{} {:.2}", s.is_square(), s.area());
}

