#[derive(Debug)]
struct Product {
    name: String,
    price: f64,
    quantity: u32,
}

impl Product {
    fn new(name: &str, price: f64, quantity: u32) -> Product {
        Product { name: String::from(name), price, quantity }
    }

    fn value(&self) -> f64 {
        self.price * self.quantity as f64
    }
}

fn main() {
    let mut items = vec![
        Product::new("bread", 2.50, 3),
        Product::new("cheese", 7.40, 1),
        Product::new("milk", 1.20, 6),
        Product::new("honey", 5.90, 2),
        Product::new("eggs", 3.00, 4),
    ];

    items.sort_by(|a, b| b.value().partial_cmp(&a.value()).unwrap());

    for p in &items {
        println!("{} {:.2}", p.name, p.value());
    }

    let total: f64 = items.iter().map(|p| p.value()).sum();
    println!("{:.2}", total);
    println!("{}", items.iter().filter(|p| p.value() > 15.0).count());
}
